/*@@SAFELAB_LIB@@*/

// ---- Shared helpers (same block in every SafeLab workflow) ----
const rowsOf = (node) => $(node).all().map((i) => i.json).filter((r) => r && Object.keys(r).length);
const now = $now.setZone('Asia/Ho_Chi_Minh');
const today = now.toFormat('yyyy-MM-dd');
const nowIso = now.toFormat("yyyy-MM-dd'T'HH:mm:ssZZ"); // e.g. 2026-10-11T21:30:00+07:00
const year = now.year;
const esc = SafeLab.escapeHtml;
const text = (v) => (v === null || v === undefined ? '' : String(v).trim());
const lower = (v) => text(v).toLowerCase();
// Google Sheets treats text starting with = + - @ as a formula: prefix ' so it is stored as plain text.
const sheetRow = (row) => Object.fromEntries(Object.entries(row).map(([k, v]) =>
  [k, typeof v === 'string' && /^[=+\-@]/.test(v) ? "'" + v : v]));
const audit = (actor, action, entity, entityId, details) =>
  sheetRow({ ts: nowIso, actor: actor || 'system', action, entity, entity_id: entityId, details: text(details).slice(0, 1000) });
const link = (url, label) =>
  (text(url) ? `<a href="${esc(url)}">${esc(label)}</a>` : `${esc(label)} (link not configured in CONFIG)`);
const mail = (to, subject, body) => ({
  to: [...new Set([].concat(to).map(lower).filter(Boolean))].join(', '),
  subject: text(subject).replace(/\s+/g, ' '),
  html: `<div style="font-family:Arial,sans-serif;font-size:14px;line-height:1.5;color:#111">${body}` +
    '<p style="color:#6b7280;font-size:12px;margin-top:24px">Automated message from SafeLab (lab-safety approval system).</p></div>',
});
const cfg = SafeLab.configMap(rowsOf('Read CONFIG'));

// ---- 09 Incident / CAPA: F06 incident -> INCIDENTS + CAPA; F07 inspection -> CAPA ----
const coordinator = lower(cfg.SAFETY_COORDINATOR_EMAIL);
const incidentIds = rowsOf('Read INCIDENTS').map((r) => r.incident_id);
const capaIds = rowsOf('Read CAPA').map((r) => r.capa_id);
const triggerRows = (node) => ($(node).isExecuted ? rowsOf(node) : []); // only one trigger runs per execution
const in14Days = now.plus({ days: 14 }).toFormat('yyyy-MM-dd');
const table = (pairs) => '<table style="border-collapse:collapse">' + pairs.map(([k, v]) =>
  `<tr><th style="text-align:left;vertical-align:top;padding:4px 8px;border:1px solid #ddd;background:#f3f4f6">${esc(k)}</th>` +
  `<td style="padding:4px 8px;border:1px solid #ddd">${esc(v).replace(/\r?\n/g, '<br>')}</td></tr>`).join('') + '</table>';

const incidents = [];
const capas = [];
const auditRows = [];
const emails = [];

// ---- F06 incident / near miss ----
for (const r of triggerRows('F06 row added')) {
  const reporter = lower(r['Email Address']);
  const incidentId = SafeLab.nextId('INC', year, incidentIds);
  incidentIds.push(incidentId);
  const injured = text(r['Was anyone injured?']).toUpperCase() === 'YES';
  const severity = text(r['Severity']).toUpperCase();
  const incident = {
    incident_id: incidentId,
    type: text(r['Type']),
    occurred_at: text(r['Date and time of event']),
    lab: text(r['Lab / room']),
    reporter_email: reporter,
    description: text(r['What happened?']),
    injury: injured ? 'YES' : 'NO',
    severity,
    immediate_action: text(r['Immediate action taken']),
    related_exp_id: text(r['Related experiment ID']).toUpperCase(),
    status: 'OPEN',
    reported_at: nowIso,
  };
  incidents.push(sheetRow(incident));

  const capaId = SafeLab.nextId('CAPA', year, capaIds);
  capaIds.push(capaId);
  const capa = {
    capa_id: capaId, source: 'INCIDENT', source_id: incidentId,
    action: `Investigate ${incidentId} and define corrective action`,
    owner_email: coordinator, due_date: in14Days, status: 'OPEN', created_at: nowIso, closed_at: '',
  };
  capas.push(sheetRow(capa));

  const details = table([
    ['Incident ID', incidentId], ['Type', incident.type], ['Occurred at', incident.occurred_at], ['Lab / room', incident.lab],
    ['Reported by', reporter], ['Injury', incident.injury], ['Severity', severity], ['What happened', incident.description],
    ['Immediate action', incident.immediate_action || '-'], ['Related experiment', incident.related_exp_id || '-'],
    ['CAPA created', `${capaId}: ${capa.action} (due ${in14Days})`],
  ]);
  emails.push(mail(coordinator, `[SafeLab] Incident reported – ${incidentId} (${incident.type}, ${severity})`,
    `<h2>New ${esc(incident.type || 'incident')} report: ${esc(incidentId)}</h2>` + details +
    `<p>A CAPA (${esc(capaId)}) has been assigned to you, due ${esc(in14Days)}.</p>`));
  if (injured || severity === 'HIGH') {
    emails.push(mail(cfg.PI_EMAIL, `[SafeLab] [URGENT] ${injured ? 'Injury' : 'HIGH severity'} incident – ${incidentId} ${incident.lab}`,
      `<h2 style="color:#b91c1c">URGENT: ${esc(injured ? 'injury reported' : 'HIGH severity incident')} – ${esc(incidentId)}</h2>` +
      details));
  }
  auditRows.push(audit(reporter, 'INCIDENT_REPORTED', 'INCIDENTS', incidentId, `${incident.type}, ${severity}, injury ${incident.injury}, ${incident.lab}`));
  auditRows.push(audit('system', 'CAPA_CREATED', 'CAPA', capaId, `from ${incidentId}, owner ${coordinator}, due ${in14Days}`));
}

// ---- F07 safety inspection ----
for (const r of triggerRows('F07 row added')) {
  const inspector = lower(r['Email Address']);
  const lab = text(r['Lab / room']);
  const inspectionDate = SafeLab.parseDate(r['Inspection date']) || text(r['Inspection date']);
  const findings = text(r['Findings']);
  const action = text(r['Corrective action required']);
  if (!action) {
    auditRows.push(audit(inspector, 'INSPECTION_RECORDED', 'F07_RESPONSES', `${lab} ${inspectionDate}`,
      `no corrective action; findings: ${findings}`));
    continue;
  }
  const capaId = SafeLab.nextId('CAPA', year, capaIds);
  capaIds.push(capaId);
  const owner = lower(r['Action owner email']) || coordinator;
  const due = SafeLab.parseDate(r['Due date']);
  capas.push(sheetRow({
    capa_id: capaId, source: 'INSPECTION', source_id: `${lab} ${inspectionDate}`,
    action, owner_email: owner, due_date: due, status: 'OPEN', created_at: nowIso, closed_at: '',
  }));
  emails.push(mail([owner, coordinator], `[SafeLab] Corrective action assigned – ${capaId} (${lab})`,
    `<h2>Corrective action assigned: ${esc(capaId)}</h2>` +
    table([['Lab / room', lab], ['Inspection date', inspectionDate], ['Inspected by', inspector], ['Findings', findings],
      ['Corrective action', action], ['Owner', owner], ['Due date', due || 'not set']]) +
    '<p>Please complete the action and inform the safety coordinator so the CAPA can be closed.</p>'));
  auditRows.push(audit(inspector, 'CAPA_CREATED', 'CAPA', capaId, `inspection ${lab} ${inspectionDate}, owner ${owner}, due ${due || '-'}`));
}

return [{ json: { incidents, capas, audit: auditRows, emails: emails.filter((e) => e.to) } }];
